function form(){return{id:$("experiment-id").value||crypto.randomUUID(),name:$("name").value.trim(),strains:$("strains").value.trim(),start:$("shift-start").value,end:$("shift-end").value,from:$("start-temp").value,to:$("target-temp").value,tasks:tasks.map(([name,s,e])=>({name,start:$(s).value,end:$(e).value})).filter(x=>x.start||x.end)}}
function check(x){let errors=[],warnings=[];if(!x.name)errors.push("Give this experiment a name or generation.");if(!x.start||!x.end)errors.push("Choose both temperature-shift dates.");if(x.from===""||x.to==="")errors.push("Enter both temperatures.");if(x.start&&x.end&&x.end<x.start)errors.push("The temperature shift cannot end before it starts.");x.tasks.forEach(t=>{if(!t.start||!t.end)errors.push(`${t.name} needs both a start and end date (or clear both).`);else if(t.end<t.start)errors.push(`${t.name} cannot end before it starts.`);else if(t.start<x.start||t.end>x.end)warnings.push(`${t.name} extends outside the temperature-shift window.`)});for(let i=0;i<x.tasks.length;i++)for(let j=i+1;j<x.tasks.length;j++)if(x.tasks[i].start<=x.tasks[j].end&&x.tasks[j].start<=x.tasks[i].end)warnings.push(`${x.tasks[i].name} overlaps with ${x.tasks[j].name}.`);return{errors,warnings}}
function render(x){$("schedule-title").textContent=x.name;$("schedule-summary").textContent=`${x.from}°C → ${x.to}°C · ${pretty(x.start)} to ${pretty(x.end)}${x.strains?` · ${x.strains}`:""}`;let days=[],d=date(x.start),end=date(x.end);while(d<=end){let day=dateValue(d),entries=[];if(day===x.start)entries.push(`🌡️ Begin temperature shift: ${x.from}°C → ${x.to}°C`);if(day===x.end)entries.push(`🌡️ End temperature-shift window (${x.to}°C)`);x.tasks.forEach(t=>{if(day===t.start)entries.push(t.start===t.end?`• ${t.name}`:`▶ Begin ${t.name.toLowerCase()}`);if(day===t.end&&t.end!==t.start)entries.push(`✓ End ${t.name.toLowerCase()}`)});days.push(`<article class="day"><b>${pretty(day)}</b><div>${entries.length?entries.map(e=>`<div class="task">${e}</div>`).join(""):`<span class="hint">No scheduled task</span>`}</div></article>`);d.setDate(d.getDate()+1)}$("schedule").innerHTML=days.join("");$("schedule-section").classList.remove("hidden")}
function saved(){try{return JSON.parse(localStorage.getItem(key))||[]}catch{return[]}}function saveList(){let list=saved(),box=$("saved-experiments");box.innerHTML=list.length?list.map(x=>`<div class="saved-card"><div><h3>${x.name}</h3><p>${pretty(x.start)}–${pretty(x.end)} · ${x.from}°C → ${x.to}°C</p></div><button class="secondary" data-load="${x.id}">Open</button></div>`).join(""):`<p class="hint">No saved experiments yet.</p>`;box.querySelectorAll("[data-load]").forEach(b=>b.onclick=()=>{let x=saved().find(y=>y.id===b.dataset.load);current=x;$("experiment-id").value=x.id;$("name").value=x.name;$("strains").value=x.strains;$("shift-start").value=x.start;$("shift-end").value=x.end;$("start-temp").value=x.from;$("target-temp").value=x.to;tasks.forEach(([n,s,e])=>{let t=x.tasks.find(v=>v.name===n)||{};$(s).value=t.start||"";$(e).value=t.end||""});render(x);window.scrollTo({top:0,behavior:"smooth"})})}
$("experiment-form").onsubmit=e=>{e.preventDefault();let x=form(),r=check(x);$("validation").innerHTML=[...r.errors.map(v=>`<p class="error">${v}</p>`),...r.warnings.map(v=>`<p class="warning">${v}</p>`)].join("");if(!r.errors.length){current=x;render(x)}};$("save-button").onclick=()=>{if(!current)return;let list=saved(),i=list.findIndex(x=>x.id===current.id);if(i<0)list.unshift(current);else list[i]=current;localStorage.setItem(key,JSON.stringify(list));saveList();$("save-button").textContent="Saved ✓";setTimeout(()=>$("save-button").textContent="Save experiment",1000)};$("clear-form").onclick=()=>{$("experiment-form").reset();$("experiment-id").value="";$("schedule-section").classList.add("hidden");$("validation").innerHTML=""};saveList();

const workflowKey="fly-manager-temperature-workflows-v1";let workflowCurrent,activeWorkflowDirection="18to25";
const formatTime=value=>new Date(value).toLocaleString(undefined,{weekday:"short",month:"short",day:"numeric",year:"numeric",hour:"numeric",minute:"2-digit"});
const addHours=(value,hours)=>new Date(new Date(value).getTime()+hours*60*60*1000);
function workflowEvents(experiment){
  const events=[];
  const isDownshift=experiment.direction==="25to18";
  const shiftDays=isDownshift?[2,4,6,8]:[3,6,9,12];
  const targetTemperature=isDownshift?18:25;
  for(let number=1;number<=3;number++){
    const start=addHours(experiment.start,(number-1)*24);
    events.push({time:start,replicate:number,kind:"Setup",text:number===1?"Day 0 setup: make new vials for virgin collection.":"Make a new Replicate: make the next virgin-collection vial.",reminder:number===1?"":"Make a new Replicate"});
    if(number===1){
      events.push({time:addHours(start,7*24),replicate:"Virgin set",kind:"Day 7",text:"Plug the shared virgin-collection vial.",reminder:"Plug virgin vial"});
      events.push({time:addHours(start,12*24),replicate:"Virgin set",kind:"Day 12",text:"Start collecting virgin flies from the shared virgin set.",reminder:"Start collecting virgin flies"});
    }
    for(const day of shiftDays){
      const shiftTime=addHours(start,day*24);
      events.push({time:shiftTime,replicate:number,kind:`Day ${day}`,text:day===shiftDays[0]?`Plug this vial, then shift it to ${targetTemperature}°C.`:`Shift/check this vial at ${targetTemperature}°C for Day ${day}.`,reminder:`Time for Day ${day} shift`});
      const maleCollectionDay=day+10;
      const maleTime=addHours(start,maleCollectionDay*24);
      const chain=`rep${number}-shift${day}`;
      events.push({time:maleTime,replicate:number,chain,task:"male-collection",kind:`Day ${maleCollectionDay}`,text:day===shiftDays[0]?`Start collecting males for the Day ${day} shift.`:`Collect males for the Day ${day} shift.`,reminder:day===shiftDays[0]?"Start collecting males":"Collect males"});
      events.push({time:maleTime,replicate:number,chain,task:"aging-start",kind:"Aging",text:"Start aging the collected flies for the fertility assay.",reminder:"Start aging flies"});
      events.push({time:addHours(maleTime,3*24),replicate:number,chain,task:"fertility-setup",kind:"Fertility assay",text:"Set up the fertility assay.",reminder:"Set up fertility assay"});
      events.push({time:addHours(maleTime,4*24),replicate:number,chain,task:"discard-males",kind:"Fertility assay",text:"Discard the male flies from the vial.",reminder:"Discard male flies"});
      events.push({time:addHours(maleTime,10*24),replicate:number,chain,task:"plug-assay",kind:"Fertility assay",text:"Plug the fertility-assay vial.",reminder:"Plug fertility-assay vial"});
      events.push({time:addHours(maleTime,17*24),replicate:number,chain,task:"fly-count",kind:"Fly count",text:"Start counting flies.",reminder:"Start counting flies"});
    }
  }
  events.filter(event=>event.chain&&event.task).forEach(anchor=>{
    const replacement=experiment.overrides&&experiment.overrides[`${anchor.chain}:${anchor.task}`];
    if(!replacement)return;
    const delta=new Date(replacement).getTime()-anchor.time.getTime();
    events.filter(event=>event.chain===anchor.chain&&event.time>=anchor.time).forEach(event=>{event.time=new Date(event.time.getTime()+delta);event.modified=true});
  });
  const decision=experiment.backupDecision;
  const firstMaleDay=shiftDays[0]+10;
  let planned=decision&&decision.outcome==="enough"?events.filter(event=>!(typeof event.replicate==="number"&&event.replicate>decision.replicate&&event.time>addHours(experiment.start,(decision.replicate-1+firstMaleDay)*24))):events;
  const lastCount=planned.filter(event=>event.kind==="Fly count").sort((a,b)=>a.time-b.time).at(-1);
  if(lastCount)planned.push({time:addHours(lastCount.time,7*24),replicate:"Experiment",kind:"Experiment end",text:"Experiment concludes seven days after the final fly-count start.",reminder:"Experiment concludes"});
  return planned.sort((a,b)=>a.time-b.time);
}
let workflowReplicate=1;
const replicateLabel=number=>number===1?"Original vial":number===2?"Replicate 1":number===3?"Replicate 2":String(number);
function ensureReplicateChoices(){if($("workflow-replicate-tabs"))return;$("workflow-schedule").insertAdjacentHTML("beforebegin",`<div id="workflow-replicate-tabs" class="view-switch" aria-label="Vial schedule"><button class="secondary" type="button" data-workflow-replicate="1">Original</button><button class="secondary" type="button" data-workflow-replicate="2">Replicate 1</button><button class="secondary" type="button" data-workflow-replicate="3">Replicate 2</button></div>`);document.querySelectorAll("[data-workflow-replicate]").forEach(button=>button.onclick=()=>{workflowReplicate=Number(button.dataset.workflowReplicate);if(workflowCurrent)showWorkflow(workflowCurrent)})}
function eventsForReplicate(events){return events.filter(event=>event.replicate===workflowReplicate||(workflowReplicate===1&&(event.replicate==="Virgin set"||event.replicate==="Experiment")))}
function showWorkflow(experiment){const events=workflowEvents(experiment),next=events.find(event=>event.time>=new Date())||events[events.length-1],shown=eventsForReplicate(events),direction=experiment.direction==="25to18"?"25°C → 18°C":"18°C → 25°C",isSaved=workflowSaved().some(record=>record.id===experiment.id);ensureReplicateChoices();$("workflow-title").textContent=`${experiment.genotype} · ${direction} · ${replicateLabel(workflowReplicate)}`;$("workflow-summary").textContent=`Next task: ${replicateLabel(next.replicate)} · ${next.kind} — ${formatTime(next.time)}. ${next.text}`;$("workflow-schedule").innerHTML=shown.map(event=>`<article class="day"><b>${formatTime(event.time)}</b><div><div class="task"><strong>${replicateLabel(event.replicate)} · ${event.kind}</strong><br>${event.text}${event.reminder?`<br><span class="reminder">Reminder: “${event.reminder}”</span>`:""}</div></div></article>`).join("")||`<p class="hint">No remaining tasks are planned for this vial.</p>`;document.querySelectorAll("[data-workflow-replicate]").forEach(button=>button.classList.toggle("active-view",Number(button.dataset.workflowReplicate)===workflowReplicate));$("workflow-save").classList.toggle("hidden",isSaved);showBackupDecision(experiment);showWorkflowGantt(experiment,shown);applyWorkflowView();$("workflow-schedule-section").classList.remove("hidden")}

let workflowView="list";
function ganttColor(event){if(event.replicate==="Virgin set")return"#ad6b1d";if(event.reminder&&event.reminder.includes("males"))return"#496f9b";if(event.reminder&&event.reminder.includes("shift"))return"#315c43";return"#7c4e8e"}
function showWorkflowGantt(experiment,events){const start=new Date(experiment.start),end=events[events.length-1].time,days=Math.ceil((end-start)/86400000),left=140,width=730,rowHeight=55,rows=[1,2,3,"Virgin set"],height=70+rows.length*rowHeight;let svg=`<svg viewBox="0 0 900 ${height}" role="img" aria-label="Gantt chart for ${experiment.genotype}" xmlns="http://www.w3.org/2000/svg"><rect width="900" height="${height}" fill="white"/>`;for(let day=0;day<=days;day+=3){const x=left+width*day/days;svg+=`<line x1="${x}" y1="35" x2="${x}" y2="${height-15}" stroke="#cbd9cf"/><text x="${x}" y="23" text-anchor="middle" font-size="12" fill="#17251c">Day ${day}</text>`}rows.forEach((row,index)=>{const y=62+index*rowHeight;svg+=`<text x="130" y="${y+5}" text-anchor="end" font-size="13" fill="#17251c">${row==="Virgin set"?"Virgin set":`Replicate ${row}`}</text><line x1="${left}" y1="${y}" x2="${left+width}" y2="${y}" stroke="#809287" stroke-width="2"/>`;events.filter(event=>event.replicate===row).forEach(event=>{const day=(event.time-start)/86400000,x=left+width*day/days,label=event.kind.replace("Day ","D");svg+=`<circle cx="${x}" cy="${y}" r="7" fill="${ganttColor(event)}"><title>${formatTime(event.time)} — ${event.text}</title></circle><text x="${x}" y="${y-11}" text-anchor="middle" font-size="10" fill="#17251c">${label}</text>`})});svg+="</svg>";$("workflow-gantt").innerHTML=`<div class="gantt-legend"><span class="gantt-key"><i class="gantt-dot gantt-setup"></i>Setup / replicate</span><span class="gantt-key"><i class="gantt-dot gantt-shift"></i>Shift</span><span class="gantt-key"><i class="gantt-dot gantt-virgin"></i>Virgin set</span><span class="gantt-key"><i class="gantt-dot gantt-male"></i>Male collection</span></div><div class="gantt-wrap">${svg}</div>`}
function applyWorkflowView(){const isGantt=workflowView==="gantt";$("workflow-schedule").classList.toggle("hidden",isGantt);$("workflow-gantt").classList.toggle("hidden",!isGantt);document.querySelectorAll("[data-workflow-view]").forEach(button=>button.classList.toggle("active-view",button.dataset.workflowView===workflowView))}
document.querySelectorAll("[data-workflow-view]").forEach(button=>button.onclick=()=>{workflowView=button.dataset.workflowView;applyWorkflowView()});
function exportWorkflowPdf(view){if(!workflowCurrent)return;const title=$(`${"workflow-title"}`).textContent,sections=[];if(view==="list"||view==="both")sections.push(`<h2>List schedule</h2>${$("workflow-schedule").innerHTML}`);if(view==="gantt"||view==="both")sections.push(`<h2>Gantt chart</h2>${$("workflow-gantt").innerHTML}`);const printWindow=window.open("","_blank");if(!printWindow)return;printWindow.document.write(`<!doctype html><html><head><title>${title}</title><style>body{font:14px/1.4 Arial,sans-serif;color:#17251c;margin:28px}h1{font-size:22px}h2{margin-top:28px}.day{display:grid;grid-template-columns:180px 1fr;gap:16px;padding:10px 0;border-top:1px solid #cbd9cf}.task{border-left:4px solid #315c43;background:#eef5ef;padding:8px}.hint{color:#526159}.gantt-wrap{overflow:visible}.gantt-wrap svg{width:100%;height:auto}.gantt-legend{display:flex;gap:14px;flex-wrap:wrap}.gantt-key{display:inline-flex;align-items:center;gap:4px}.gantt-dot{width:10px;height:10px;border-radius:50%;display:inline-block}.gantt-shift{background:#315c43}.gantt-male{background:#496f9b}.gantt-virgin{background:#ad6b1d}.gantt-setup{background:#7c4e8e}@media print{body{margin:12mm}.day{break-inside:avoid}}</style></head><body><h1>${title}</h1><p>${$("workflow-summary").textContent}</p>${sections.join("")}</body></html>`);printWindow.document.close();printWindow.focus();setTimeout(()=>printWindow.print(),300)}
document.querySelectorAll("[data-pdf-view]").forEach(button=>button.onclick=()=>exportWorkflowPdf(button.dataset.pdfView));
function workflowSaved(){try{return JSON.parse(localStorage.getItem(workflowKey))||[]}catch{return[]}}
function showWorkflowSaved(){const records=workflowSaved(),box=$("workflow-saved");box.innerHTML=records.length?records.map(record=>`<div class="saved-card"><div><h3>${record.genotype}</h3><p>${record.direction==="25to18"?"25°C → 18°C":"18°C → 25°C"} · Setup: ${formatTime(record.start)}</p></div><button class="secondary" data-workflow-load="${record.id}">Open</button></div>`).join(""):`<p class="hint">No saved experiments yet.</p>`;box.querySelectorAll("[data-workflow-load]").forEach(button=>button.onclick=()=>{workflowCurrent=workflowSaved().find(record=>record.id===button.dataset.workflowLoad);activeWorkflowDirection=workflowCurrent.direction||"18to25";setWorkflowDirection(activeWorkflowDirection);$("workflow-genotype").value=workflowCurrent.genotype;$("workflow-start").value=workflowCurrent.start;showWorkflow(workflowCurrent);showBarcode(workflowCurrent);window.scrollTo({top:0,behavior:"smooth"})})}
function persistWorkflowDecision(experiment){const records=workflowSaved(),index=records.findIndex(record=>record.id===experiment.id);if(index>=0){records[index]=experiment;localStorage.setItem(workflowKey,JSON.stringify(records));showWorkflowSaved();renderExperiments();renderTasks()}}
function showBackupDecision(experiment){const box=$("backup-decision"),isDownshift=experiment.direction==="25to18",firstMaleDay=(isDownshift?2:3)+10,decision=experiment.backupDecision,now=new Date();let html="";if(decision&&decision.outcome==="enough"){const remaining=decision.replicate===1?"Replicate 1 and Replicate 2":"Replicate 2";html+=`<strong>Male-availability checkpoint complete</strong><p>${replicateLabel(decision.replicate)} provided males for ${escapeText(experiment.genotype)}. ${remaining} is no longer needed, so its future tasks have been removed from the schedule and Tasks list.</p>`}else if(decision&&decision.outcome==="all-used"){html+=`<strong>Male-availability checkpoint complete</strong><p>All three vials have been checked. Proceed with the number of males available for ${escapeText(experiment.genotype)}.</p>`}else{const replicate=decision&&decision.outcome==="continue"?decision.replicate:1,checkTime=addHours(experiment.start,(replicate-1+firstMaleDay)*24),name=replicateLabel(replicate);if(now>=checkTime){html+=`<strong>Male-availability checkpoint</strong><p>Is male available from ${name.toLowerCase()} of ${escapeText(experiment.genotype)}?</p><button type="button" data-male-decision="enough">Yes</button><button class="secondary" type="button" data-male-decision="not-enough">No</button><p class="hint">This question stays here until you answer it.</p>`}else{html+=`<strong>Next male-availability checkpoint</strong><p>Check ${name.toLowerCase()} for males on ${formatTime(checkTime)}.</p>`}}
  const countEvents=workflowEvents({...experiment,backupDecision:null}).filter(event=>event.task==="fertility-setup"),checks=experiment.countingCheckpoints||{};const due=countEvents.filter(event=>now>=addHours(event.time,14*24)&&checks[event.chain]!=="started");if(due.length){const event=due[0],dueTime=addHours(event.time,14*24);html+=`<hr><strong>Counting checkpoint</strong><p>Fourteen days have passed since the fertility assay for ${replicateLabel(event.replicate)}. Has fly counting started for ${escapeText(experiment.genotype)}?</p><button type="button" data-count-check="${event.chain}" data-count-answer="started">Yes — counting started</button><button class="secondary" type="button" data-count-check="${event.chain}" data-count-answer="not-yet">Not yet</button><p class="hint">Due: ${formatTime(dueTime)}. This question remains visible until counting has started.</p>`}box.innerHTML=html;box.querySelectorAll("[data-male-decision]").forEach(button=>button.onclick=()=>{const replicate=decision&&decision.outcome==="continue"?decision.replicate:1;if(button.dataset.maleDecision==="enough"){experiment.backupDecision={outcome:"enough",replicate};}else if(replicate<3){experiment.backupDecision={outcome:"continue",replicate:replicate+1};}else{experiment.backupDecision={outcome:"all-used",replicate:3};}persistWorkflowDecision(experiment);showWorkflow(experiment)});box.querySelectorAll("[data-count-check]").forEach(button=>button.onclick=()=>{experiment.countingCheckpoints=experiment.countingCheckpoints||{};experiment.countingCheckpoints[button.dataset.countCheck]=button.dataset.countAnswer;persistWorkflowDecision(experiment);showWorkflow(experiment)})}
$("workflow-18-form").onsubmit=event=>{event.preventDefault();const genotype=$("workflow-genotype").value.trim(),start=$("workflow-start").value;if(!genotype||!start){$("workflow-validation").innerHTML="<p class=\"error\">Enter both the fly genotype and the exact setup date/time.</p>";return}workflowCurrent={id:crypto.randomUUID(),genotype,start,direction:activeWorkflowDirection};$("workflow-validation").innerHTML="";$("workflow-barcode-section").classList.add("hidden");showWorkflow(workflowCurrent)};
$("workflow-save").onclick=()=>{if(!workflowCurrent)return;workflowCurrent.barcode=barcodeFor(workflowCurrent);const records=workflowSaved(),index=records.findIndex(record=>record.id===workflowCurrent.id);if(index<0)records.unshift(workflowCurrent);else records[index]=workflowCurrent;localStorage.setItem(workflowKey,JSON.stringify(records));showWorkflowSaved();showBarcode(workflowCurrent);renderExperiments();renderTasks();showWorkflow(workflowCurrent)};showWorkflowSaved();

const code39={"0":"nnnwwnwnn","1":"wnnwnnnnw","2":"nnwwnnnnw","3":"wnwwnnnnn","4":"nnnwwnnnw","5":"wnnwwnnnn","6":"nnwwwnnnn","7":"nnnwnnwnw","8":"wnnwnnwnn","9":"nnwwnnwnn","A":"wnnnnwnnw","B":"nnwnnwnnw","C":"wnwnnwnnn","D":"nnnnwwnnw","E":"wnnnwwnnn","F":"nnwnwwnnn","G":"nnnnnwwnw","H":"wnnnnwwnn","I":"nnwnnwwnn","J":"nnnnwwwnn","K":"wnnnnnnww","L":"nnwnnnnww","M":"wnwnnnnwn","N":"nnnnwnnww","O":"wnnnwnnwn","P":"nnwnwnnwn","Q":"nnnnnnwww","R":"wnnnnnwwn","S":"nnwnnnwwn","T":"nnnnwnwwn","U":"wwnnnnnnw","V":"nwwnnnnnw","W":"wwwnnnnnn","X":"nwnnwnnnw","Y":"wwnnwnnnn","Z":"nwwnwnnnn","-":"nwnnnnwnw",".":"wwnnnnwnn"," ":"nwwnnnwnn","*":"nwnnwnwnn"};
function barcodeFor(record){return record.barcode||`EXP${record.id.replace(/-/g,"").slice(0,10).toUpperCase()}`}
function barcodeSvg(value){let x=12,rects=[],parts=`*${value}*`;for(const char of parts){for(let i=0;i<code39[char].length;i++){const width=code39[char][i]==="w"?5:2;if(i%2===0)rects.push(`<rect x="${x}" y="8" width="${width}" height="64"/>`);x+=width}x+=2}return `<svg viewBox="0 0 ${x+12} 80" role="img" aria-label="Barcode ${value}" xmlns="http://www.w3.org/2000/svg"><rect width="100%" height="100%" fill="white"/>${rects.join("")}</svg>`}
function showBarcode(record){const code=barcodeFor(record);record.barcode=code;$("workflow-barcode").innerHTML=`<div class="barcode-wrap">${barcodeSvg(code)}<p class="barcode-code">${code}</p></div>`;$("workflow-barcode-section").classList.remove("hidden")}
function openWorkflowByCode(code){if(openVirginByCode(code))return;const record=workflowSaved().find(item=>barcodeFor(item)===code.trim().toUpperCase());if(!record){$("barcode-lookup-message").innerHTML="<p class=\"error\">No saved experiment or virgin stock has that barcode.</p>";return}workflowCurrent=record;activeWorkflowDirection=record.direction||"18to25";setWorkflowDirection(activeWorkflowDirection);$("workflow-genotype").value=record.genotype;$("workflow-start").value=record.start;showWorkflow(record);showBarcode(record);$("barcode-lookup-message").innerHTML="";page("workflow-18-page")}
$("barcode-lookup-form").onsubmit=event=>{event.preventDefault();openWorkflowByCode($("barcode-lookup").value)};
function ensureCameraBarcodeScanner(){if($("camera-barcode-button"))return;const form=$("barcode-lookup-form");form.insertAdjacentHTML("afterend",`<button id="camera-barcode-button" class="secondary" type="button">📷 Scan barcode with camera</button><div id="camera-barcode-panel" class="hidden" style="margin-top:.8rem"><video id="camera-barcode-video" playsinline style="width:100%;max-width:420px;border-radius:10px;background:#18221b"></video><br><button id="camera-barcode-cancel" class="secondary" type="button" style="margin-top:.5rem">Cancel camera scan</button><p id="camera-barcode-message" class="hint" aria-live="polite"></p></div>`);let stream=null,scanning=false;const stop=()=>{scanning=false;if(stream)stream.getTracks().forEach(track=>track.stop());stream=null;$("camera-barcode-panel").classList.add("hidden")},scan=async()=>{if(!scanning)return;try{const codes=await new BarcodeDetector({formats:["code_39","code_128","qr_code"]}).detect($("camera-barcode-video"));if(codes.length){const value=codes[0].rawValue;$("barcode-lookup").value=value;stop();openWorkflowByCode(value);return}}catch{$("camera-barcode-message").textContent="Unable to read that barcode yet. Hold the camera steady and try again."}requestAnimationFrame(scan)};$("camera-barcode-button").onclick=async()=>{if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){$("barcode-lookup-message").innerHTML=`<p class="error">Camera scanning needs the app to be opened from a secure website. For now, type the code or use a Bluetooth barcode scanner.</p>`;return}if(!("BarcodeDetector" in window)){$("barcode-lookup-message").innerHTML=`<p class="error">This browser does not support built-in barcode scanning. You can still type the code or use a Bluetooth barcode scanner.</p>`;return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}}});const video=$("camera-barcode-video");video.srcObject=stream;await video.play();$("camera-barcode-panel").classList.remove("hidden");$("camera-barcode-message").textContent="Point your camera at the barcode.";scanning=true;scan()}catch{$("barcode-lookup-message").innerHTML=`<p class="error">Camera access was not available. Check the browser permission, then try again.</p>`}};$("camera-barcode-cancel").onclick=stop}
// Camera barcode scanning is intentionally unavailable in this version.
// Barcode labels stay on saved items for identification only.
document.querySelector(".scan-panel")?.classList.add("hidden");

let modifierContext="",modifierRecord=null;
const asDateTimeInput=value=>{const d=new Date(value);return `${dateValue(d)}T${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`};
function modifierEvents(record){const selected=new Set(record.selectedReplicates&&record.selectedReplicates.length?record.selectedReplicates:[1,2,3]),events=workflowEvents({...record,overrides:{}}).filter(event=>selected.has(event.replicate)),context=modifierContext.toLowerCase();if(context==="all")return events.filter(event=>["male-collection","aging-start","fertility-setup","fly-count"].includes(event.task));if(context.includes("collection")||context.includes("experiment schedule"))return events.filter(event=>event.task==="male-collection");if(context.includes("aging"))return events.filter(event=>event.task==="aging-start");if(context.includes("fertility"))return events.filter(event=>event.task==="fertility-setup");if(context.includes("fly count"))return events.filter(event=>event.task==="fly-count");return []}
document.querySelectorAll(".modifier-choice").forEach(button=>button.onclick=()=>{modifierContext=button.dataset.modifier;modifierRecord=null;$("modifier-title").textContent=`Modify: ${modifierContext}`;$("modifier-message").textContent="Enter a saved experiment barcode, then load its editable tasks.";$("modifier-task").innerHTML="<option>Load an experiment first</option>";$("modifier-task").disabled=true;page("modifier-detail-page")});
document.querySelectorAll(".modifier-choice").forEach(button=>{if(!button.dataset.modifier.toLowerCase().includes("experiment schedule"))return;button.dataset.modifier=button.dataset.modifier.replace("experiment schedule","fly collection");button.querySelector("b").innerHTML="🪰<br>Fly Collection";button.querySelector("span").textContent="Modify the date or time for collecting flies."});
$("modifier-back").onclick=()=>window.controlRecord?openExperimentControl(window.controlRecord):page("home-page");
$("modifier-load").onclick=()=>{const code=$("modifier-experiment").value.trim().toUpperCase();modifierRecord=workflowSaved().find(record=>barcodeFor(record)===code);if(!modifierRecord){$("modifier-message").textContent="No saved experiment has that barcode.";return}const editable=modifierEvents(modifierRecord),select=$("modifier-task"),taskName={"male-collection":"Male collection","aging-start":"Aging of flies","fertility-setup":"Fertility assay setup","fly-count":"Fly counting"};if(!editable.length){$("modifier-message").textContent="No editable tasks are available for this experiment.";select.disabled=true;return}select.innerHTML=editable.map(event=>`<option value="${event.chain}:${event.task}" data-time="${asDateTimeInput(event.time)}">${taskName[event.task]} — ${replicateLabel(event.replicate)} — ${formatTime(event.time)}</option>`).join("");select.disabled=false;$("modifier-time").value=select.options[0].dataset.time;$("modifier-message").textContent="Choose one task, then enter its new date and time."};
