$("modifier-save").onclick=()=>{const key=$("modifier-task").value,time=$("modifier-time").value;if(!modifierRecord||!key||!time){$("modifier-message").textContent="Choose a task and enter its new date/time.";return}modifierRecord.overrides=modifierRecord.overrides||{};modifierRecord.overrides[key]=time;const records=workflowSaved(),index=records.findIndex(record=>record.id===modifierRecord.id);records[index]=modifierRecord;localStorage.setItem(workflowKey,JSON.stringify(records));renderExperiments();renderTasks();openExperimentControl(modifierRecord)};

const virginStockKey="fly-manager-ongoing-virgin-stock-v1";
function nextFriday(){const day=new Date();day.setHours(12,0,0,0);let offset=(5-day.getDay()+7)%7;if(offset===0)offset=7;day.setDate(day.getDate()+offset);return dateValue(day)}
function virginStock(){try{return JSON.parse(localStorage.getItem(virginStockKey))||null}catch{return null}}
function ensureVirginStock(){let stock=virginStock();if(stock){stock.batches.forEach(batch=>batch.vials=batch.vials||batch.quantity||20);localStorage.setItem(virginStockKey,JSON.stringify(stock));return stock}stock={start:nextFriday(),batches:[{batch:"A",vials:20,barcode:"VIRGIN-A"},{batch:"B",vials:20,barcode:"VIRGIN-B"}]};localStorage.setItem(virginStockKey,JSON.stringify(stock));return stock}
function showVirginBatches(){const stock=ensureVirginStock(),box=$("virgin-batches");box.innerHTML=stock.batches.map(batch=>`<div class="saved-card"><div><h3>Batch ${batch.batch} · ${batch.vials} vials</h3><p>Ongoing saved virgin stock · barcode: ${batch.barcode}</p></div></div>`).join("")}
function virginStockTasks(stock=ensureVirginStock()){const start=stock.start,tasks=[];for(let index=0;index<16;index++){const date=dateValue(addHours(start,index*7*24));if(index%2===0){tasks.push({date,batch:"A",task:"Flip virgin females"},{date,batch:"B",task:"Plug virgin females"})}else{tasks.push({date,batch:"B",task:"Flip virgin females"},{date,batch:"A",task:"Plug virgin females"})}}return tasks}
function showVirginStock(){const stock=ensureVirginStock(),box=$("virgin-stock-tasks");box.innerHTML=virginStockTasks(stock).map(task=>`<article class="day"><b>${pretty(task.date)}</b><div class="task"><strong>Batch ${task.batch}</strong><br>${task.task}. <span class="hint">Time is flexible today.</span></div></article>`).join("");$("virgin-barcodes").innerHTML=stock.batches.map(batch=>`<div class="barcode-wrap">${barcodeSvg(batch.barcode)}<p class="barcode-code">${batch.barcode}</p></div>`).join("")}
function nextVirginTask(batch){return virginStockTasks().find(task=>task.batch===batch.batch&&task.date>=dateValue(new Date()))||virginStockTasks().filter(task=>task.batch===batch.batch).at(-1)}
function openVirginByCode(code){const stock=ensureVirginStock(),batch=stock.batches.find(item=>item.barcode===code.trim().toUpperCase());if(!batch)return false;const task=nextVirginTask(batch);$("virgin-barcode-info").innerHTML=`<div class="backup-decision"><strong>Batch ${batch.batch}</strong><p>Availability: ongoing stock with ${batch.vials} vials.</p><p>Next management task: ${task.task} on ${pretty(task.date)}.</p></div>`;$("barcode-lookup-message").innerHTML="";page("virgin-stock-page");return true}
$("virgin-availability-form").onsubmit=event=>{event.preventDefault();const needed=$("virgin-needed-date").value,box=$("virgin-availability-result");if(!needed)return;ensureVirginStock();box.innerHTML=`<p><strong>Yes — virgin flies should be available on ${pretty(needed)}.</strong></p>`};showVirginBatches();showVirginStock();

const completedTaskKey="fly-manager-completed-tasks-v1",observationKey="fly-manager-observations-v1";
let experimentView="future",observationDirection="18to25",todayTasks=[];
const escapeText=value=>String(value).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\"/g,"&quot;");
function experimentStatus(record){const events=workflowEvents(record),start=new Date(record.start),end=events[events.length-1].time,now=new Date();if(now<start)return"future";if(now>end)return"completed";return"ongoing"}
function ongoingExperiments(direction){return workflowSaved().filter(record=>experimentStatus(record)==="ongoing"&&(!direction||record.direction===direction))}
function openWorkflowRecord(record){workflowCurrent=record;workflowReplicate=1;activeWorkflowDirection=record.direction||"18to25";setWorkflowDirection(activeWorkflowDirection);$("workflow-genotype").value=record.genotype;$("workflow-start").value=record.start;showWorkflow(record);showBarcode(record);page("workflow-18-page")}
let savedScheduleView="list",chosenScheduleReplicates=[];
function selectedReplicates(record){return record.selectedReplicates&&record.selectedReplicates.length?record.selectedReplicates:[1,2,3]}
function chosenScheduleEvents(record){const selected=new Set(selectedReplicates(record));return workflowEvents(record).filter(event=>selected.has(event.replicate)||(event.replicate==="Virgin set"&&selected.has(1))||event.replicate==="Experiment")}
function ensureSavedScheduleViewer(){if($("saved-schedule-page"))return;document.querySelector("main").insertAdjacentHTML("beforeend",`<section id="saved-schedule-page" class="page hidden"><button class="secondary back" type="button" id="saved-schedule-back">← Experiment</button><div class="intro"><h2 id="saved-schedule-title">Schedule</h2><p>Choose the vial schedule(s) you want to use, then save that choice.</p></div><section class="panel"><h3>Vial schedule options</h3><div class="view-switch" id="saved-replicate-options"><button class="secondary" type="button" data-saved-replicate="1">Original</button><button class="secondary" type="button" data-saved-replicate="2">Replicate 1</button><button class="secondary" type="button" data-saved-replicate="3">Replicate 2</button></div><button id="save-replicate-options" type="button">Save selected vial options</button><p id="saved-replicate-message" class="hint"></p></section><section class="panel"><div class="view-switch"><button class="secondary active-view" type="button" data-saved-schedule-view="list">List schedule</button><button class="secondary" type="button" data-saved-schedule-view="gantt">Gantt chart</button></div><div id="saved-schedule-list"></div><div id="saved-schedule-gantt" class="hidden"></div></section></section>`);$("saved-schedule-back").onclick=()=>openExperimentControl(window.controlRecord);document.querySelectorAll("[data-saved-replicate]").forEach(button=>button.onclick=()=>{const number=Number(button.dataset.savedReplicate);chosenScheduleReplicates=chosenScheduleReplicates.includes(number)?chosenScheduleReplicates.filter(item=>item!==number):[...chosenScheduleReplicates,number];renderSavedScheduleViewer(window.controlRecord)});$("save-replicate-options").onclick=()=>{if(!chosenScheduleReplicates.length){$("saved-replicate-message").textContent="Choose at least one vial schedule first.";return}const record=window.controlRecord,records=workflowSaved(),index=records.findIndex(item=>item.id===record.id);record.selectedReplicates=[...chosenScheduleReplicates].sort();records[index]=record;localStorage.setItem(workflowKey,JSON.stringify(records));renderTasks();$("saved-replicate-message").textContent="Your vial schedule options are saved. The modifier will now show tasks only for these vial schedules.";renderSavedScheduleViewer(record)};document.querySelectorAll("[data-saved-schedule-view]").forEach(button=>button.onclick=()=>{savedScheduleView=button.dataset.savedScheduleView;renderSavedScheduleViewer(window.controlRecord)})}
function renderSavedScheduleViewer(record){const events=chosenScheduleEvents({...record,selectedReplicates:chosenScheduleReplicates.length?chosenScheduleReplicates:selectedReplicates(record)});$("saved-schedule-list").innerHTML=events.map(event=>`<article class="day"><b>${formatTime(event.time)}</b><div class="task"><strong>${replicateLabel(event.replicate)} · ${event.kind}</strong><br>${event.text}</div></article>`).join("");showWorkflowGantt(record,events);$("saved-schedule-gantt").innerHTML=$("workflow-gantt").innerHTML;const gantt=savedScheduleView==="gantt";$("saved-schedule-list").classList.toggle("hidden",gantt);$("saved-schedule-gantt").classList.toggle("hidden",!gantt);document.querySelectorAll("[data-saved-replicate]").forEach(button=>button.classList.toggle("active-view",chosenScheduleReplicates.includes(Number(button.dataset.savedReplicate))));document.querySelectorAll("[data-saved-schedule-view]").forEach(button=>button.classList.toggle("active-view",button.dataset.savedScheduleView===savedScheduleView))}
function openSavedSchedule(record){ensureSavedScheduleViewer();window.controlRecord=record;chosenScheduleReplicates=[...selectedReplicates(record)];$("saved-schedule-title").textContent=`(${barcodeFor(record)}) ${record.genotype}`;$("saved-replicate-message").textContent="";renderSavedScheduleViewer(record);page("saved-schedule-page")}
function exportExperimentData(record){const tasks=workflowEvents(record).map(event=>({time:event.time.toISOString(),vial:replicateLabel(event.replicate),kind:event.kind,task:event.text,completed:!!completedTasks()[`temperature:${record.id}:${event.chain||event.kind}:${event.time.toISOString()}`]})),notes=observations().filter(note=>note.experimentId===record.id),exportData={experiment:record,schedule:tasks,notes,exportedAt:new Date().toISOString()};const blob=new Blob([JSON.stringify(exportData,null,2)],{type:"application/json"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`${barcodeFor(record)}-complete-experiment.json`;link.click();URL.revokeObjectURL(link.href)}
function ensureExperimentControl(){if($("experiment-control-page"))return;document.querySelector("main").insertAdjacentHTML("beforeend",`<section id="experiment-control-page" class="page hidden"><button class="secondary back" type="button" id="experiment-control-back">← Experiments</button><div class="intro"><h2 id="experiment-control-title">Experiment</h2><p id="experiment-control-summary"></p></div><section class="panel"><h2>Open this experiment</h2><div class="menu-grid"><button class="menu-card" type="button" data-control-action="schedule"><b>📋<br>Schedule</b><span>Choose either the list schedule or Gantt chart.</span></button><button class="menu-card" type="button" data-control-action="modifier"><b>✏️<br>Schedule Modifier</b><span>Change collection, aging, fertility-assay, or fly-count dates.</span></button><button class="menu-card" type="button" data-control-action="record"><b>📝<br>Task Record / Notes</b><span>Record what happened for this experiment.</span></button></div><button id="experiment-control-export" class="secondary hidden" type="button">Export completed experiment data</button><p id="experiment-control-message" class="hint"></p></section></section>`);$("experiment-control-back").onclick=()=>{renderExperiments();page("experiments-page")};$("experiment-control-export").onclick=()=>{if(window.controlRecord)exportExperimentData(window.controlRecord)};document.querySelectorAll("[data-control-action]").forEach(button=>button.onclick=()=>{const record=workflowSaved().find(item=>item.id===button.dataset.recordId)||window.controlRecord;if(!record)return;if(button.dataset.controlAction==="schedule")openSavedSchedule(record);if(button.dataset.controlAction==="modifier")openModifierFor(record);if(button.dataset.controlAction==="record")openRecordFor(record)})}
function openExperimentControl(record){ensureExperimentControl();window.controlRecord=record;const status=experimentStatus(record);$("experiment-control-title").textContent=`(${barcodeFor(record)}) ${record.genotype}`;$("experiment-control-summary").textContent=`${record.direction==="25to18"?"25°C → 18°C":"18°C → 25°C"} · ${status==="ongoing"?"current":status} experiment`;$("experiment-control-message").textContent=status==="ongoing"?"Choose the workspace you need.":"Completed experiments remain available for schedules and modifications, but new observations are limited to current experiments.";$("experiment-control-export").classList.toggle("hidden",status!=="completed");document.querySelectorAll("[data-control-action]").forEach(button=>button.dataset.recordId=record.id);page("experiment-control-page")}
function openRecordFor(record){if(experimentStatus(record)!=="ongoing"){openExperimentControl(record);$("experiment-control-message").textContent="This experiment is complete, so observations can no longer be added.";return}observationDirection=record.direction;$("observation-title").textContent=`${record.genotype} — Task Record / Observations`;$("observation-date").value=dateValue(new Date());renderObservationOptions();$("observation-experiment").value=record.id;renderObservations();page("observation-page")}
function openModifierFor(record){modifierContext="all";modifierRecord=null;$("modifier-title").textContent=`Modify: ${record.genotype}`;$("modifier-experiment").value=barcodeFor(record);$("modifier-message").textContent="Choose the planned collection, aging, fertility-assay, or fly-count date to change.";$("modifier-load").click();page("modifier-detail-page")}
function renderExperiments(){const records=workflowSaved().filter(record=>experimentStatus(record)===experimentView),box=$("experiments-list"),label=experimentView==="ongoing"?"current":experimentView;box.innerHTML=records.length?records.map(record=>{const events=workflowEvents(record),end=events[events.length-1].time;return `<div class="saved-card"><div><button class="secondary" data-open-experiment="${record.id}" type="button">(${barcodeFor(record)}) ${escapeText(record.genotype)}</button><p>${record.direction==="25to18"?"25°C → 18°C":"18°C → 25°C"} · ${label} · ${formatTime(record.start)} to ${formatTime(end)}</p></div>${threeDotMenu("experiment",record.id)}</div>`}).join(""):`<p class="hint">No ${label} experiments.</p>`;box.querySelectorAll("[data-open-experiment]").forEach(button=>button.onclick=()=>openExperimentControl(workflowSaved().find(record=>record.id===button.dataset.openExperiment)));box.querySelectorAll("[data-edit-experiment]").forEach(button=>button.onclick=()=>editExperiment(button.dataset.editExperiment));box.querySelectorAll("[data-delete-experiment]").forEach(button=>button.onclick=()=>deleteExperiment(button.dataset.deleteExperiment))}
$("experiments-page").querySelector('[data-experiment-view="ongoing"]').textContent="Current Experiments";
document.querySelectorAll("[data-experiment-view]").forEach(button=>button.onclick=()=>{experimentView=button.dataset.experimentView;document.querySelectorAll("[data-experiment-view]").forEach(item=>item.classList.toggle("active-view",item===button));renderExperiments()});
document.querySelectorAll('[data-page="experiments-page"]').forEach(button=>button.onclick=()=>{renderExperiments();page("experiments-page")});
function completedTasks(){try{return JSON.parse(localStorage.getItem(completedTaskKey))||{}}catch{return{}}}
function temperatureTasks(forCalendar=false){const now=new Date(),today=dateValue(now),items=[];ongoingExperiments().forEach(record=>{const selected=new Set(selectedReplicates(record));workflowEvents(record).filter(event=>selected.has(event.replicate)||(event.replicate==="Virgin set"&&selected.has(1))||event.replicate==="Experiment").forEach(event=>{const eventDay=dateValue(event.time);if((forCalendar&&event.time>=now)||(!forCalendar&&eventDay===today)){items.push({id:`temperature:${record.id}:${event.chain||event.kind}:${event.time.toISOString()}`,source:"Temperature shift",title:`${record.genotype}: ${event.text}`,time:event.time})}})});return items}
function virginTasks(forCalendar=false){const now=new Date(),today=dateValue(now);return virginStockTasks().filter(task=>forCalendar?task.date>=today:task.date===today).map(task=>({id:`virgin:${task.date}:${task.batch}:${task.task}`,source:"Virgin management",title:`Batch ${task.batch}: ${task.task}`,date:task.date}))}
function weeklyTemperatureInputTasks(forCalendar=false){const now=new Date(),tasks=[],first=new Date(now);first.setSeconds(0,0);const untilMonday=(1-first.getDay()+7)%7;first.setDate(first.getDate()+untilMonday);first.setHours(7,30,0,0);if(first<now)first.setDate(first.getDate()+7);if(!forCalendar&&now.getDay()!==1)return[];if(!forCalendar){const today=new Date();today.setHours(7,30,0,0);return[{id:`temperature-input:${dateValue(today)}`,source:"Temperature monitor",title:"Enter weekly temperature and humidity data",time:today}]}for(let week=0;week<16;week++){const time=new Date(first);time.setDate(time.getDate()+week*7);tasks.push({id:`temperature-input:${dateValue(time)}`,source:"Temperature monitor",title:"Enter weekly temperature and humidity data",time})}return tasks}
function allTasks(forCalendar=false){return [...temperatureTasks(forCalendar),...virginTasks(forCalendar),...stockManagementTasks(forCalendar),...weeklyTemperatureInputTasks(forCalendar)]}
function renderTasks(){todayTasks=allTasks(),box=$("task-list"),done=completedTasks();box.innerHTML=todayTasks.length?todayTasks.map((task,index)=>`<button class="saved-card ${done[task.id]?"secondary":""}" type="button" data-task-index="${index}"><div><h3>${done[task.id]?"✓ ":""}${escapeText(task.title)}</h3><p>${task.source}${task.time?` · ${formatTime(task.time)}`:" · time flexible"}</p></div><span>${done[task.id]?"Completed":"Mark complete"}</span></button>`).join(""):`<p class="hint">No temperature-shift, virgin-management, or strain-inventory tasks are scheduled for today.</p>`;box.querySelectorAll("[data-task-index]").forEach(button=>button.onclick=()=>{const task=todayTasks[Number(button.dataset.taskIndex)],done=completedTasks();if(done[task.id])delete done[task.id];else done[task.id]=new Date().toISOString();localStorage.setItem(completedTaskKey,JSON.stringify(done));renderTasks()})}
document.querySelectorAll('[data-page="tasks-page"]').forEach(button=>button.onclick=()=>{renderTasks();page("tasks-page")});
function icsTimestamp(value){return new Date(value).toISOString().replace(/[-:]/g,"").replace(/\.\d{3}/,"")}
function exportActiveCalendar(){const tasks=allTasks(true),now=icsTimestamp(new Date());const events=tasks.map((task,index)=>{const uid=`fly-manager-${index}-${Date.now()}@local`;if(task.date){const start=task.date.replace(/-/g,"");const end=dateValue(addHours(task.date,24)).replace(/-/g,"");return `BEGIN:VEVENT\r\nUID:${uid}\r\nDTSTAMP:${now}\r\nDTSTART;VALUE=DATE:${start}\r\nDTEND;VALUE=DATE:${end}\r\nSUMMARY:${task.title}\r\nEND:VEVENT`}const start=icsTimestamp(task.time),end=icsTimestamp(addHours(task.time,1));return `BEGIN:VEVENT\r\nUID:${uid}\r\nDTSTAMP:${now}\r\nDTSTART:${start}\r\nDTEND:${end}\r\nSUMMARY:${task.title}\r\nEND:VEVENT`}).join("\r\n");const blob=new Blob([`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Fly Manager//EN\r\n${events}\r\nEND:VCALENDAR`],{type:"text/calendar"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download="fly-manager-active-tasks.ics";link.click();URL.revokeObjectURL(link.href)}
$("calendar-export").onclick=exportActiveCalendar;
function observations(){try{return JSON.parse(localStorage.getItem(observationKey))||[]}catch{return[]}}
